/* Separate Platinum exchange ledger. Balances and authorization are server-owned. */
window.MioExchange=(()=>{
 let api,allowed=false,identity=null,epoch=0,offset=0,busy=false,receiptTurn=0,historyRows=[];
 const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=v=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:4}).format(Number(v)||0);
 const stamp=v=>new Date(v).toLocaleString('en-GB',{timeZone:'Asia/Karachi',dateStyle:'medium',timeStyle:'short'});
 function mount(options){api=options;const p=document.createElement('section');p.id='page-exchange';p.className='page';p.innerHTML=`<div class="heading"><div><div class="eyebrow">Platinum only</div><h1>Exchange Wallet</h1><p>Your member transfers, separate from your Cash Wallet.</p></div><label class="ex-year">Period<select id="exchangeYear"><option value="">All time</option>${Array.from({length:new Date().getFullYear()-2019},(_,i)=>new Date().getFullYear()-i).map(y=>`<option>${y}</option>`).join('')}</select></label></div><p id="exchangeStatus" role="status" aria-live="polite"></p><div class="ex-metrics" id="exchangeMetrics"></div><div class="ex-forms"><section class="card"><div class="card-head"><div><h2>Fund your Exchange Wallet</h2><p>From your Cash Wallet to your own Exchange Wallet.</p></div></div><form id="exchangeFundForm" class="card-body form"><p id="exchangeCashBalance" class="helper"></p><label>Amount (MIO)<input name="amount" type="number" min="0.0001" max="1000000000" step="0.0001" required></label><button class="btn primary" type="submit">Review funding</button></form></section><section class="card"><div class="card-head"><div><h2>Send to a member</h2><p>Payments leave your Exchange Wallet only.</p></div></div><form id="exchangeSendForm" class="card-body form"><label>Recipient member code<input name="code" placeholder="MIO-…" required autocomplete="off"></label><label>Amount (MIO)<input name="amount" type="number" min="0.0001" max="1000000000" step="0.0001" required></label><label>Note (optional)<input name="note" maxlength="300"></label><p class="helper">Sent to the member’s Cash Wallet, or Exchange Wallet if they also hold Platinum.</p><button class="btn primary" type="submit">Review transfer</button></form></section></div><section class="card ex-history"><div class="card-head"><div><h2>Exchange history</h2><p>Self funding is recorded separately from members’ sent and received totals. Times: Pakistan.</p></div><label>Direction<select id="exchangeDirection"><option value="all">All activity</option><option value="received">Received</option><option value="sent">Sent</option><option value="fund">Self funding</option></select></label></div><div class="card-body"><div class="ex-table-wrap"><table><thead><tr><th>Date & time</th><th>Member</th><th>Direction</th><th>Amount</th><th>Reference / note</th><th>Status</th><th>Receipt</th></tr></thead><tbody id="exchangeRows"></tbody></table></div><div class="ex-pagination"><button id="exchangePrevious" class="btn small" type="button">Previous</button><span id="exchangePage"></span><button id="exchangeNext" class="btn small" type="button">Next</button></div></div></section>`;
 ($('memberPageContent')||$('main-content')).append(p);
 for(const id of ['exchangeYear','exchangeDirection'])$(id).addEventListener('change',()=>{offset=0;refresh()});
 $('exchangeRows').addEventListener('click',e=>{const button=e.target.closest('[data-exchange-receipt]');if(button)openReceipt(button)});
 $('exchangePrevious').onclick=()=>{offset=Math.max(0,offset-25);refresh()};$('exchangeNext').onclick=()=>{offset+=25;refresh()};
 $('exchangeFundForm').addEventListener('submit',e=>{e.preventDefault();send(e.currentTarget,'fund')});$('exchangeSendForm').addEventListener('submit',e=>{e.preventDefault();send(e.currentTarget,'send')});
 const form=$('transferForm');if(form){form.insertAdjacentHTML('beforebegin','<div id="exchangeCashNotice" hidden><p>Platinum transfers use your Exchange Wallet. Fund it from Cash Wallet first, then send to a member.</p><button class="btn primary" type="button" data-page="exchange">Open Exchange Wallet →</button></div>');const card=form.closest('.card');if(card?.querySelector('.card-head p'))card.querySelector('.card-head p').textContent='Send from Cash Wallet to a Platinum member’s Exchange Wallet.';const helper=form.querySelector('.helper');if(helper)helper.textContent='Other members cannot receive direct Cash Wallet transfers.';}
 setAccess(null,null);
 }
 function setAccess(code,uid){const next=!!uid&&code==='PREMIUM';if(identity!==uid||allowed!==next){epoch++;receiptTurn++;historyRows=[];window.MioTransferReceipt?.clear();offset=0;for(const id of ['exchangeMetrics','exchangeRows','exchangeStatus'])$(id)?.replaceChildren();for(const id of ['exchangeFundForm','exchangeSendForm']){const f=$(id);f?.reset();if(f){delete f.dataset.key;delete f.dataset.signature}}}identity=uid;allowed=next;if($('exchangeCashNotice'))$('exchangeCashNotice').hidden=!allowed;if($('transferForm'))$('transferForm').hidden=allowed;if(!allowed&&$('page-exchange')?.classList.contains('active'))api.go(uid?'wallet':'login');}
 async function refresh(){if(!allowed)return;const turn=++epoch,uid=identity;$('exchangeStatus').textContent='Loading exchange activity…';try{const r=await api.rpc('my_exchange_wallet',{p_year:$('exchangeYear').value?Number($('exchangeYear').value):null,p_direction:$('exchangeDirection').value,p_offset:offset,p_limit:25});if(turn!==epoch||uid!==identity||!allowed)return;if(r.error)throw r.error;const d=r.data;historyRows=d.rows;const period=$('exchangeYear').value||'All time';$('exchangeMetrics').innerHTML=[['Available balance',d.balance,'Current Exchange Wallet'],['Total received',d.received,period+' · From members'],['Total sent',d.sent,period+' · To members'],['Self funding',d.funded,period+' · From your Cash Wallet']].map(([title,n,note],i)=>`<article class="card ex-metric ${i===0?'ex-primary':''}"><span>${title}</span><strong>${money(n)} <small>MIO</small></strong><small>${esc(note)}</small></article>`).join('');$('exchangeCashBalance').textContent='Available Cash Wallet: '+money(d.cash_balance)+' MIO';$('exchangeRows').innerHTML=d.rows.length?d.rows.map(r=>`<tr><td>${esc(stamp(r.created_at))}</td><td><strong>${esc(r.full_name)}</strong><small>${esc(r.member_code)}</small></td><td><span class="ex-tag ${esc(r.direction)}">${r.direction==='fund'?'Self funding':r.direction==='sent'?'↑ Sent':'↓ Received'}</span></td><td class="ex-amount">${r.direction==='sent'?'−':'+'}${money(r.amount)} MIO</td><td><small class="ex-reference">${esc(r.id)}</small>${r.note?`<small>${esc(r.note)}</small>`:''}</td><td><span class="ex-tag">Completed</span></td><td><button type="button" class="btn small" data-exchange-receipt="${esc(r.id)}" aria-label="View receipt ${esc(r.id)}">View</button></td></tr>`).join(''):'<tr><td colspan="7" class="ex-empty">No exchange activity for this selection.</td></tr>';$('exchangePrevious').disabled=offset===0;$('exchangeNext').disabled=offset+25>=d.total;$('exchangePage').textContent=d.total?`${offset+1}–${Math.min(offset+25,d.total)} of ${d.total}`:'0 records';$('exchangeStatus').textContent='';}catch(e){if(turn===epoch){historyRows=[];$('exchangeMetrics').replaceChildren();$('exchangeRows').replaceChildren();$('exchangeStatus').textContent=e.message||'Exchange activity could not load';}}}
 async function openReceipt(button){
  if(!allowed)return;const row=historyRows.find(r=>r.id===button.dataset.exchangeReceipt);if(!row)return;
  const turn=++receiptTurn,uid=identity;button.disabled=true;
  try{const r=await api.rpc('lookup_mio_transfer_receipt',{p_transfer_id:row.id});if(turn!==receiptTurn||uid!==identity||!allowed)return;if(r.error)throw r.error;
   const info=Array.isArray(r.data)?r.data[0]:r.data;
   if(!info||info.transfer_id!==row.id||![info.sender_id,info.recipient_id].includes(uid))throw Error('Receipt could not be verified for this account');
   const wallet=value=>value==='exchange'?'Exchange Wallet':value==='cash'?'Cash Wallet':'Wallet unavailable';
   window.MioTransferReceipt.show({id:info.transfer_id,date:stamp(info.created_at),amount:money(info.amount),title:row.direction==='fund'?'Wallet funding completed':'Transfer completed',direction:row.direction==='fund'?'You funded your Exchange Wallet':row.direction==='sent'?'You sent MIO Points':'You received MIO Points',sender:{name:info.sender_name,code:info.sender_code},receiver:{name:info.recipient_name,code:info.recipient_code},source:wallet(row.source_wallet),destination:wallet(row.destination_wallet),note:row.note||''});
  }catch(e){if(turn===receiptTurn&&uid===identity&&allowed)api.error(e)}finally{button.disabled=false}
 }
 async function send(form,kind){if(busy||!allowed)return;busy=true;const uid=identity,button=form.querySelector('button[type=submit]');button.disabled=true;try{const amount=form.elements.amount.value;let code='',name='your Exchange Wallet',note='';if(kind==='send'){code=form.elements.code.value.trim();note=form.elements.note.value.trim();const recipient=await api.rpc('lookup_transfer_recipient',{p_code:code});if(recipient.error)throw recipient.error;if(!recipient.data?.[0])throw Error('No eligible recipient found');code=recipient.data[0].member_code;name=recipient.data[0].full_name+' ('+code+')';}
 const description=(kind==='fund'?'Fund':'Send')+' '+amount+' MIO '+(kind==='fund'?'from Cash Wallet into ':'from Exchange Wallet to ')+name;
 if(api.isAdmin())await api.confirm(description);
 const pin=await api.pin(description);if(!pin)return;if(uid!==identity||!allowed)throw Error('Session changed. Please try again');
 const signature=JSON.stringify([kind,amount,code,note]);if(form.dataset.signature!==signature){form.dataset.signature=signature;form.dataset.key=api.idKey()}
 const args={p_amount:amount,p_idempotency_key:form.dataset.key,p_transaction_pin:pin};if(kind==='send')Object.assign(args,{p_recipient_code:code,p_note:note});
 const r=await api.rpc(kind==='fund'?'fund_exchange_wallet':'send_exchange_mio',args);if(r.error)throw r.error;form.reset();delete form.dataset.key;delete form.dataset.signature;api.notify(kind==='fund'?'Exchange Wallet funded.':'Exchange transfer completed.');await api.reload();await refresh();
 }catch(e){api.error(e)}finally{busy=false;button.disabled=false}}
 return {mount,setAccess,refresh};
})();
